#include "viewer.h"
#include <stdlib.h>
#include <stdio.h>
#include <wchar.h>
#include <string.h>
#include <ctype.h>

void settings_defaults(Settings *s){memset(s,0,sizeof(*s));s->initialFit=FIT_SHRINK;s->sort=SORT_NATURAL;s->loop=TRUE;s->highQuality=TRUE;s->checkerboard=FALSE;s->autoOrientation=TRUE;s->statusbar=TRUE;s->background=RGB(32,32,32);s->zoomStep=1.25;s->maxCacheBytes=256ULL*1024ULL*1024ULL;s->x=CW_USEDEFAULT;s->y=CW_USEDEFAULT;s->width=1024;s->height=768;s->startMode=VIEW_NORMAL;}
static int eq(const char *a,const char *b){return _stricmp(a,b)==0;}
static void set(Settings *s,const char *section,const char *key,const char *v){
 if(eq(section,"Window")){if(eq(key,"X"))s->x=atoi(v);else if(eq(key,"Y"))s->y=atoi(v);else if(eq(key,"Width"))s->width=atoi(v);else if(eq(key,"Height"))s->height=atoi(v);else if(eq(key,"Maximized"))s->maximized=atoi(v)!=0;else if(eq(key,"Mode")){s->startMode=eq(v,"Simple")?VIEW_SIMPLE:VIEW_NORMAL;}else if(eq(key,"BackgroundColor")){unsigned r,g,b;if(sscanf(v,"#%2x%2x%2x",&r,&g,&b)==3)s->background=RGB(r,g,b);}else if(eq(key,"ShowStatusBar"))s->statusbar=atoi(v)!=0;}
 else if(eq(section,"Display")){if(eq(key,"FitMode")){if(eq(v,"FitAll"))s->initialFit=FIT_ALL;else if(eq(v,"Actual"))s->initialFit=FIT_ACTUAL;else if(eq(v,"Width"))s->initialFit=FIT_WIDTH;else if(eq(v,"Height"))s->initialFit=FIT_HEIGHT;else s->initialFit=FIT_SHRINK;}else if(eq(key,"ZoomStep"))s->zoomStep=strtod(v,NULL);else if(eq(key,"ZoomLock"))s->zoomLock=atoi(v)!=0;else if(eq(key,"Interpolation"))s->highQuality=eq(v,"HighQuality");else if(eq(key,"Transparency"))s->checkerboard=eq(v,"Checkerboard");else if(eq(key,"AutoOrientation"))s->autoOrientation=atoi(v)!=0;}
 else if(eq(section,"Navigation")){if(eq(key,"SortBy")){if(eq(v,"Name"))s->sort=SORT_NAME;else if(eq(v,"Date"))s->sort=SORT_DATE;else if(eq(v,"Size"))s->sort=SORT_SIZE;else s->sort=SORT_NATURAL;}else if(eq(key,"Descending"))s->descending=atoi(v)!=0;else if(eq(key,"Loop"))s->loop=atoi(v)!=0;}
 else if(eq(section,"Cache")){if(eq(key,"MaxMemoryMB"))s->maxCacheBytes=(size_t)strtoull(v,NULL,10)*1024ULL*1024ULL;}
}
void settings_load(App *a){settings_defaults(&a->cfg);DWORD n=GetModuleFileNameW(NULL,a->iniPath,32768);if(!n||n>=32768){a->iniPath[0]=0;return;}wchar_t *slash=wcsrchr(a->iniPath,L'\\');if(!slash)return;wcscpy(slash+1,L"LiteViewer.ini");HANDLE h=CreateFileW(a->iniPath,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE)return;LARGE_INTEGER len;if(!GetFileSizeEx(h,&len)||len.QuadPart>1024*1024){CloseHandle(h);return;}char *buf=calloc((size_t)len.QuadPart+1,1);if(!buf){CloseHandle(h);return;}DWORD nr=0;BOOL ok=ReadFile(h,buf,(DWORD)len.QuadPart,&nr,NULL);CloseHandle(h);if(!ok){free(buf);return;}buf[nr]=0;char section[64]="";char *line=buf;while(*line){char *end=strpbrk(line,"\r\n");if(end)*end=0;char *p=line;while(*p==' '||*p=='\t')p++;if(*p=='['){char *e=strchr(p+1,']');if(e){*e=0;strncpy(section,p+1,sizeof(section)-1);section[sizeof(section)-1]=0;}}else if(*p&&*p!=';'&&*p!='#'){char *equal=strchr(p,'=');if(equal){*equal=0;char *key=p,*v=equal+1;while(*v==' '||*v=='\t')v++;char *t=key+strlen(key);while(t>key&&(t[-1]==' '||t[-1]=='\t'))*--t=0;set(&a->cfg,section,key,v);}}if(!end)break;line=end+1;while(*line=='\r'||*line=='\n')line++;}free(buf);if(a->cfg.width<240||a->cfg.width>16000)a->cfg.width=1024;if(a->cfg.height<180||a->cfg.height>16000)a->cfg.height=768;if(a->cfg.zoomStep<1.01||a->cfg.zoomStep>4)a->cfg.zoomStep=1.25;if(a->cfg.maxCacheBytes<16*1024*1024||a->cfg.maxCacheBytes>2048ULL*1024*1024)a->cfg.maxCacheBytes=256ULL*1024*1024;}
BOOL settings_save(App *a){if(!a->iniPath[0])return FALSE;const wchar_t *fit[]={L"ShrinkOnly",L"FitAll",L"Actual",L"Width",L"Height",L"ShrinkOnly"};const wchar_t *sort[]={L"NaturalName",L"Name",L"Date",L"Size"};wchar_t out[4096];int n=swprintf(out,4096,L"[General]\r\nConfigVersion=1\r\n\r\n[Window]\r\nX=%d\r\nY=%d\r\nWidth=%d\r\nHeight=%d\r\nMaximized=%d\r\nMode=%ls\r\nBackgroundColor=#%02X%02X%02X\r\nShowStatusBar=%d\r\n\r\n[Display]\r\nFitMode=%ls\r\nZoomStep=%.3f\r\nZoomLock=%d\r\nInterpolation=%ls\r\nTransparency=%ls\r\nAutoOrientation=%d\r\n\r\n[Navigation]\r\nSortBy=%ls\r\nDescending=%d\r\nLoop=%d\r\n\r\n[Cache]\r\nMaxMemoryMB=%llu\r\n",a->cfg.x,a->cfg.y,a->cfg.width,a->cfg.height,a->cfg.maximized,a->cfg.startMode==VIEW_SIMPLE?L"Simple":L"Normal",GetRValue(a->cfg.background),GetGValue(a->cfg.background),GetBValue(a->cfg.background),a->cfg.statusbar,fit[a->cfg.initialFit],a->cfg.zoomStep,a->cfg.zoomLock,a->cfg.highQuality?L"HighQuality":L"Fast",a->cfg.checkerboard?L"Checkerboard":L"Solid",a->cfg.autoOrientation,sort[a->cfg.sort],a->cfg.descending,a->cfg.loop,(unsigned long long)(a->cfg.maxCacheBytes/(1024*1024)));if(n<=0)return FALSE;int bytes=WideCharToMultiByte(CP_UTF8,0,out,n,NULL,0,NULL,NULL);if(bytes<=0)return FALSE;char *utf8=malloc(bytes);if(!utf8)return FALSE;WideCharToMultiByte(CP_UTF8,0,out,n,utf8,bytes,NULL,NULL);wchar_t tmp[32768];if(wcslen(a->iniPath)>32740){free(utf8);return FALSE;}swprintf(tmp,32768,L"%ls.tmp",a->iniPath);HANDLE h=CreateFileW(tmp,GENERIC_WRITE,0,NULL,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE){free(utf8);return FALSE;}DWORD written=0;BOOL ok=WriteFile(h,utf8,bytes,&written,NULL)&&written==(DWORD)bytes&&FlushFileBuffers(h);CloseHandle(h);free(utf8);if(ok)ok=MoveFileExW(tmp,a->iniPath,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH);if(!ok)DeleteFileW(tmp);return ok;}
